class Solution {
public:
    vector<string> commonChars(vector<string>& words) {
        vector<int> min_freq(26, INT_MAX);
        for (const string& word : words) {
            vector<int> freq(26, 0);
            for (char ch : word) {
                freq[ch - 'a']++;
            }
            for (int i = 0; i < 26; ++i) {
                min_freq[i] = min(min_freq[i], freq[i]);
            }
        }
        vector<string> res;
        for (int i = 0; i < 26; ++i) {
            for (int k = 0; k < min_freq[i]; ++k) {
                res.push_back(string(1, 'a' + i));
            }
        }
        return res;
    }
};

class Solution {
    public List<String> commonChars(String[] words) {
        int[] minFreq = new int[26];
        Arrays.fill(minFreq, Integer.MAX_VALUE);
        for (String word : words) {
            int[] freq = new int[26];
            for (char ch : word.toCharArray()) {
                freq[ch - 'a']++;
            }
            for (int i = 0; i < 26; ++i) {
                minFreq[i] = Math.min(minFreq[i], freq[i]);
            }
        }
        List<String> res = new ArrayList<>();
        for (int i = 0; i < 26; ++i) {
            for (int k = 0; k < minFreq[i]; ++k) {
                res.add(String.valueOf((char) ('a' + i)));
            }
        }
        return res;
    }
}

var commonChars = function(words) {
    const minFreq = new Array(26).fill(Infinity);
    for (const word of words) {
        const freq = new Array(26).fill(0);
        for (let i = 0; i < word.length; i++) {
            freq[word.charCodeAt(i) - 97]++;
        }
        for (let i = 0; i < 26; i++) {
            minFreq[i] = Math.min(minFreq[i], freq[i]);
        }
    }
    const res = [];
    for (let i = 0; i < 26; i++) {
        for (let k = 0; k < minFreq[i]; k++) {
            res.push(String.fromCharCode(97 + i));
        }
    }
    return res;
};
